export async function markShipped(orderId: number) {
  const order = await db.orders.get(orderId)
  if (!order) throw new NotFound(orderId)
  if (order.status === 'cancelled') return order
  await db.orders.update(orderId, { shipped: true })
  await events.emit('order.shipped', { orderId })
  return { ...order, shipped: true }
}
